{
  "explanation_fr": "Une alimentation saine est essentielle pour maintenir et restaurer la santé du corps. Les fruits, légumes, protéines maigres et céréales complètes fournissent les vitamines, minéraux et nutriments nécessaires pour renforcer le système immunitaire. Un régime équilibré aide à réparer les cellules, combat l'inflammation et accélère le processus de guérison. En choisissant des aliments naturels et non transformés, on donne à notre organisme les outils dont il a besoin pour se régénérer et retrouver son équilibre optimal."
}

// Login authentication handler with proper string comparison
public class AuthenticationHandler {
    public boolean authenticateUser(String username, String password) {
        // Fixed: Using equals() for proper string content comparison
        if (username != null && password != null && 
            username.equals("admin") && password.equals("secretpass123")) {
            return true;
        }
        return false;
    }

    private void grantAccess(boolean isAuthenticated) {
        if (isAuthenticated) {
            System.out.println("Access granted");
        } else {
            System.out.println("Access denied");
        }
    }
}
